package net.flovex.core.market;
import net.flovex.core.data.Storage;import net.flovex.core.economy.EconomyHook;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.ItemStack;import org.bukkit.util.io.BukkitObjectInputStream;import org.bukkit.util.io.BukkitObjectOutputStream;import java.io.*;import java.sql.*;import java.util.*;
public final class Marketplace{
 private final Storage db;private final EconomyHook eco;private final double tax;private final int maxListings;private final long duration;private final double min,max;
 public Marketplace(Storage d,EconomyHook e,org.bukkit.configuration.file.FileConfiguration c){db=d;eco=e;tax=c.getDouble("marketplace.tax-percent",5);maxListings=c.getInt("marketplace.max-auctions",10);duration=c.getLong("marketplace.listing-hours",48)*3600000L;min=c.getDouble("marketplace.min-price",1);max=c.getDouble("marketplace.max-price",1e12);}
 public boolean list(Player p,double price){ItemStack hand=p.getInventory().getItemInMainHand();if(!eco.available()||hand.getType().isAir()||!Double.isFinite(price)||price<min||price>max)return false;try{if(db.rows("SELECT id FROM auctions WHERE seller=? AND sold=0 AND expires>?",p.getUniqueId().toString(),System.currentTimeMillis()).size()>=maxListings)return false;byte[] bytes=encode(hand.clone());db.update("INSERT INTO auctions(seller,item,price,created,expires) VALUES(?,?,?,?,?)",p.getUniqueId().toString(),bytes,price,System.currentTimeMillis(),System.currentTimeMillis()+duration);p.getInventory().setItemInMainHand(null);return true;}catch(Exception e){return false;}}
 public List<Map<String,Object>> listings(){try{return db.rows("SELECT * FROM auctions WHERE sold=0 AND expires>? ORDER BY created DESC LIMIT 45",System.currentTimeMillis());}catch(Exception e){return List.of();}}
 public boolean buy(Player buyer,long id){try{var a=db.rows("SELECT * FROM auctions WHERE id=? AND sold=0 AND expires>?",id,System.currentTimeMillis());if(a.isEmpty())return false;var row=a.getFirst();UUID seller=UUID.fromString((String)row.get("seller"));double price=((Number)row.get("price")).doubleValue();if(seller.equals(buyer.getUniqueId())||!eco.withdraw(buyer.getUniqueId(),price))return false;byte[] item=(byte[])row.get("item");try{db.transaction(c->{try(PreparedStatement u=c.prepareStatement("UPDATE auctions SET sold=1 WHERE id=? AND sold=0")){u.setLong(1,id);if(u.executeUpdate()!=1)throw new IllegalStateException("Listing already sold");}try(PreparedStatement q=c.prepareStatement("INSERT INTO claims(owner,kind,item,source,created) VALUES(?,?,?,?,?)")){q.setString(1,buyer.getUniqueId().toString());q.setString(2,"ITEM");q.setBytes(3,item);q.setString(4,"auction:"+id);q.setLong(5,System.currentTimeMillis());q.executeUpdate();q.setString(1,seller.toString());q.setString(2,"MONEY");q.setBytes(3,null);q.setString(4,"auction-proceeds:"+id);q.setLong(5,System.currentTimeMillis());q.setDouble(6,price*(1-tax/100));}return null;});}catch(Exception e){eco.deposit(buyer.getUniqueId(),price);return false;}double payout=price*(1-tax/100);db.update("INSERT INTO claims(owner,kind,amount,source,created) VALUES(?,?,?,?,?)",seller.toString(),"MONEY",payout,"auction-proceeds:"+id,System.currentTimeMillis());return true;}catch(Exception e){return false;}}
 public int claim(Player p){int n=0;try{for(var row:db.rows("SELECT * FROM claims WHERE owner=? AND claimed=0 ORDER BY id",p.getUniqueId().toString())){long id=((Number)row.get("id")).longValue();String kind=(String)row.get("kind");if(kind.equals("MONEY")){double a=((Number)row.get("amount")).doubleValue();if(!eco.deposit(p.getUniqueId(),a))continue;}else{ItemStack item=decode((byte[])row.get("item"));if(p.getInventory().firstEmpty()<0)break;p.getInventory().addItem(item);}if(db.update("UPDATE claims SET claimed=1 WHERE id=? AND claimed=0",id)==1)n++;}}catch(Exception ignored){}return n;}
 public boolean createOrder(Player p,Material m,int amount,double unit){if(!eco.available()||m==null||m.isAir()||amount<1||amount>100000||!Double.isFinite(unit)||unit<=0)return false;double reserve=amount*unit;if(!eco.withdraw(p.getUniqueId(),reserve))return false;try{db.update("INSERT INTO orders(buyer,material,remaining,unit_price,reserved,created,expires) VALUES(?,?,?,?,?,?,?)",p.getUniqueId().toString(),m.name(),amount,unit,reserve,System.currentTimeMillis(),System.currentTimeMillis()+72*3600000L);return true;}catch(Exception e){eco.deposit(p.getUniqueId(),reserve);return false;}}
 public double sell(Player p,ItemStack stack,org.bukkit.configuration.file.FileConfiguration worth){if(!eco.available()||stack==null||stack.getType().isAir())return 0;int remaining=stack.getAmount();double earned=0;try{for(var o:db.rows("SELECT * FROM orders WHERE material=? AND remaining>0 AND expires>? ORDER BY unit_price DESC",stack.getType().name(),System.currentTimeMillis())){if(remaining<=0)break;UUID buyer=UUID.fromString((String)o.get("buyer"));if(buyer.equals(p.getUniqueId()))continue;long id=((Number)o.get("id")).longValue();int qty=Math.min(remaining,((Number)o.get("remaining")).intValue());double unit=((Number)o.get("unit_price")).doubleValue(),payment=qty*unit;if(!eco.deposit(p.getUniqueId(),payment))continue;int next=((Number)o.get("remaining")).intValue()-qty;try{byte[] item=encode(new ItemStack(stack.getType(),qty));db.update("UPDATE orders SET remaining=?,reserved=? WHERE id=?",next,next*unit,id);db.update("INSERT INTO claims(owner,kind,item,source,created) VALUES(?,?,?,?,?)",buyer.toString(),"ITEM",item,"order:"+id,System.currentTimeMillis());remaining-=qty;earned+=payment;}catch(Exception ex){eco.withdraw(p.getUniqueId(),payment);}}}catch(Exception ignored){}double fixed=worth.getDouble("prices."+stack.getType().name(),0);if(remaining>0&&fixed>0){double payment=remaining*fixed;if(eco.deposit(p.getUniqueId(),payment)){earned+=payment;remaining=0;}}int sold=stack.getAmount()-remaining;if(sold>0)stack.setAmount(remaining);return earned;}
 private byte[] encode(ItemStack i)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();try(BukkitObjectOutputStream o=new BukkitObjectOutputStream(b)){o.writeObject(i);}return b.toByteArray();}
 private ItemStack decode(byte[] b)throws Exception{try(BukkitObjectInputStream i=new BukkitObjectInputStream(new ByteArrayInputStream(b))){return (ItemStack)i.readObject();}}
}